command:
$ErrorActionPreference = 'Continue'
# #997 MIGRATION — MIG-15. Two claims that need to be exact rather than approximately right.
#
# 1. "Exactly one Ollama." Two ollama.exe processes are present. If they are two independent servers
#    the acceptance test FAILED; if one is the serve process and the other is the model runner it
#    spawned, it passed. A process count cannot tell those apart -- the parent/child chain can.
# 2. The card's resting temperature. With a model resident it sat at 78-84 C and would not fall;
#    it only dropped once the 5-minute keep-alive expired and the model unloaded. That distinction
#    decides whether "idle" on this card means 10 W or 59 W, and it belongs in the record.

Write-Output '--- PROCESS-TREE ---'
$procs = Get-CimInstance Win32_Process -Filter "Name = 'ollama.exe'" -ErrorAction SilentlyContinue
foreach ($p in $procs) {
    $parent = (Get-CimInstance Win32_Process -Filter "ProcessId = $($p.ParentProcessId)" -ErrorAction SilentlyContinue)
    Write-Output "pid=$($p.ProcessId) ppid=$($p.ParentProcessId) parent_name=$($parent.Name)"
    Write-Output "    cmdline=$($p.CommandLine)"
}
Write-Output '--- WHO-OWNS-THE-LISTENER ---'
Get-NetTCPConnection -LocalPort 11434 -State Listen -ErrorAction SilentlyContinue |
    ForEach-Object { "listener pid=$($_.OwningProcess) addr=$($_.LocalAddress):$($_.LocalPort)" }
Write-Output '--- SERVICE-TASK-PID-CHAIN ---'
$ps = Get-CimInstance Win32_Process -Filter "Name = 'powershell.exe'" -ErrorAction SilentlyContinue |
    Where-Object { $_.CommandLine -match 'hermes-ollama-service' }
$ps | ForEach-Object { "service_shell pid=$($_.ProcessId) ppid=$($_.ParentProcessId)" }

Write-Output '--- RESTING-TEMPERATURE-WITH-MODEL-RESIDENT ---'
try { (Invoke-RestMethod 'http://127.0.0.1:11434/api/ps' -TimeoutSec 15).models | ForEach-Object { "resident=$($_.name) size_vram=$($_.size_vram) expires=$($_.expires_at)" } } catch { Write-Output "ps_ERR=$($_.Exception.Message)" }
for ($i = 0; $i -lt 10; $i++) {
    & 'C:\Windows\System32\nvidia-smi.exe' --query-gpu=timestamp,temperature.gpu,power.draw,utilization.gpu,memory.used,clocks.sm --format=csv,noheader -i GPU-4f7d4396-9304-d12f-7e9b-7f04d1236fc2
    Start-Sleep -Seconds 20
}
Write-Output '--- AFTER-COOLDOWN-WINDOW ---'
try { $r = (Invoke-RestMethod 'http://127.0.0.1:11434/api/ps' -TimeoutSec 15).models; if ($r) { $r | ForEach-Object { "still_resident=$($_.name)" } } else { Write-Output 'no model resident' } } catch { }
& 'C:\Windows\System32\nvidia-smi.exe' --query-gpu=uuid,temperature.gpu,power.draw,memory.used --format=csv,noheader
Write-Output '--- RC ---'
